update public.ramos set def = '{"version": 2, "eximicion": null, "dudas": [], "raiz": {"id": "raiz", "nombre": "Nota final", "tipo": "grupo", "promedio": "ponderado", "hijos": [{"id": "ind", "nombre": "Nota individual (para aprobar)", "peso": 0.9, "tipo": "grupo", "promedio": "ponderado", "minimo": 3.95, "hijos": [{"id": "cr", "nombre": "Control de repaso", "peso": 0.05, "tipo": "nota", "fecha": null, "examen": false, "reemplazable": false, "minimo": null}, {"id": "p1", "nombre": "Prueba 1", "peso": 0.2, "tipo": "nota", "fecha": null, "examen": false, "reemplazable": false, "minimo": null}, {"id": "p2", "nombre": "Prueba 2", "peso": 0.2, "tipo": "nota", "fecha": null, "examen": false, "reemplazable": false, "minimo": null}, {"id": "c1", "nombre": "Control tarea 1", "peso": 0.05, "tipo": "nota", "fecha": null, "examen": false, "reemplazable": false, "minimo": null}, {"id": "c2", "nombre": "Control tarea 2", "peso": 0.05, "tipo": "nota", "fecha": null, "examen": false, "reemplazable": false, "minimo": null}, {"id": "part", "nombre": "Participación", "peso": 0.1, "tipo": "nota", "fecha": null, "examen": false, "reemplazable": false, "minimo": null}, {"id": "ex", "nombre": "Examen", "peso": 0.25, "tipo": "nota", "fecha": null, "examen": true, "reemplazable": false, "minimo": null}]}, {"id": "grp", "nombre": "Tareas grupales", "peso": 0.1, "tipo": "grupo", "promedio": "ponderado", "minimo": null, "hijos": [{"id": "t1", "nombre": "Tarea 1 grupal", "peso": 0.05, "tipo": "nota", "fecha": null, "examen": false, "reemplazable": false, "minimo": null}, {"id": "t2", "nombre": "Tarea 2 grupal", "peso": 0.05, "tipo": "nota", "fecha": null, "examen": false, "reemplazable": false, "minimo": null}]}]}, "reglas": ["Control de repaso 5%, pruebas 20% c/u, examen 25%, tareas 10% c/u (5% entrega grupal + 5% control individual), participación 10%.", "Para aprobar cuenta solo la nota individual (control de repaso, pruebas, controles de tareas, participación y examen): debe ser ≥ 4,0. Si no